import{_ as e,o as l,c as a,ag as n}from"./chunks/framework.D9ghT4bC.js";const h=JSON.parse('{"title":"图像和音频资源","description":"","frontmatter":{"title":"图像和音频资源"},"headers":[],"relativePath":"zh/Modders/Images-and-Audio.md","filePath":"zh/Modders/Images-and-Audio.md"}'),d={name:"zh/Modders/Images-and-Audio.md"};function i(s,t,r,o,c,g){return l(),a("div",null,[...t[0]||(t[0]=[n(`<h1 id="图像和音频资源" tabindex="-1">图像和音频资源 <a class="header-anchor" href="#图像和音频资源" aria-label="Permalink to &quot;图像和音频资源&quot;">​</a></h1><h2 id="图像和纹理图集" tabindex="-1">图像和纹理图集 <a class="header-anchor" href="#图像和纹理图集" aria-label="Permalink to &quot;图像和纹理图集&quot;">​</a></h2><p>图像需要在游戏使用之前&quot;打包&quot;。这个准备步骤只需要进行一次（只要原始图形没有更改）。 结果是一对或多对文件 - 一个 <a href="https://en.wikipedia.org/wiki/PNG" target="_blank" rel="noreferrer">png 格式</a>的纹理和相应的 <a href="https://en.wikipedia.org/wiki/Texture_atlas" target="_blank" rel="noreferrer">atlas</a> 文件。 如果你有一个单独的 <code>Images</code> 文件夹，默认这样的对命名为 <code>game.png</code>/<code>game.atlas</code>。 对于你的玩家来说，单个图像并不重要 - 只有组合的图像实际注册到游戏中，所以你需要将它们包含在你的仓库中并保持更新。 我们仍然建议在模组中包含原始图像，以便其他从源运行的开发人员可以访问它们。 包含原始图像后，你可以使用使用 git 的开发环境，将其链接到你的仓库，同时使用符号链接让 Unciv 看到模组 - 并在每次启动时为你打包图集。 如果你在 Unciv 的 Android 版本上开发你的模组（不推荐！），你将无法直接生成这些打包的文件。</p><h3 id="打包纹理图集的方法" tabindex="-1">打包纹理图集的方法 <a class="header-anchor" href="#打包纹理图集的方法" aria-label="Permalink to &quot;打包纹理图集的方法&quot;">​</a></h3><ul><li>纹理图集<em>无法在 Android 上打包</em>（技术原因：TexturePacker 使用 <code>java.awt</code> 进行繁重的工作，这在 Android 上不可用 0_0）</li><li>使用你的模组启动桌面版本（你的模组的主文件夹是游戏&quot;mods&quot;文件夹的子文件夹，或在那里符号链接）。这使用了<a href="https://libgdx.com/wiki/tools/texture-packer" target="_blank" rel="noreferrer">此处记录</a>的打包方法。</li><li>你可以请 Discord 服务器中的某人帮助你。</li><li>你可以使用外部工具，<a href="https://github.com/crashinvaders/gdx-texture-packer-gui" target="_blank" rel="noreferrer">例如 gdx-texture-packer-gui</a>。需要极其小心确保文件可以被 Unciv 发现并且内部相对路径正确。</li><li>你可以将<a href="https://github.com/ravignir/RekMOD/blob/master/.github/workflows/autoupdate.yml" target="_blank" rel="noreferrer">此工作流的副本</a>添加到你的模组中，以便在每次提交到仓库时自动打包图集。它应该放置在与示例相同的位置（<code>.github/workflows/autoupdate.yml</code>）。</li></ul><h3 id="渲染性能" tabindex="-1">渲染性能 <a class="header-anchor" href="#渲染性能" aria-label="Permalink to &quot;渲染性能&quot;">​</a></h3><h4 id="多个纹理图集" tabindex="-1">多个纹理图集 <a class="header-anchor" href="#多个纹理图集" aria-label="Permalink to &quot;多个纹理图集&quot;">​</a></h4><p>如果你的模组有很多图像（或很大的图像），纹理可能会&quot;溢出&quot;到额外的纹理文件中 - 2048x2048 是单个纹理包的限制。你将看到 <code>game2.png</code>，可能还有 <code>game3.png</code> 或更多出现。 这对性能不利，这就是为什么基础游戏控制哪些类型的图像一起进入一个纹理（+图集）。 这也适用于模组：不仅创建一个 Images 文件夹，而是创建多个，额外的命名为&quot;Images.xyz&quot;，其中 xyz 将成为额外纹理文件的文件名（所以不要同时使用 Images 和 Images.game - 它们会冲突）。查看 Unciv 基础游戏以更好地了解它是如何工作的。 为了最大限度地减少纹理交换，尽量按它们在游戏中需要的情况进行分组。你可以按文件夹分发，但在几个&quot;Images.xyz&quot;下具有相同的子文件夹并在它们之间分发图像也可以。</p><p>例如，你可以查看 <a href="https://github.com/carriontrooper/Alpha-Frontier" target="_blank" rel="noreferrer">Alpha Frontier 模组</a>。</p><p>模组根目录中的文件 <code>Atlases.json</code>（大写&#39;A&#39;）（不在 <code>Images</code> 或 <code>jsons</code> 中）控制加载哪些图集，这反过来控制读取哪些纹理（<code>.png</code>）文件。 此文件由内置的打包器自动创建。默认情况下只读取 <code>game.atlas</code> 文件以保持向后兼容性。 如果你使用外部工具和多个图集，你将需要自己维护此文件 - 它是一个简单的字符串 json 数组，每个字符串都是不带 <code>.atlas</code> 扩展名的文件名（保存为不带字节顺序标记的 UTF-8）。</p><h4 id="更小的图标" tabindex="-1">更小的图标 <a class="header-anchor" href="#更小的图标" aria-label="Permalink to &quot;更小的图标&quot;">​</a></h4><p>大量图集可能是由于图标很大导致的。 我们发现 100x100 像素对于大多数图标来说已经足够了。</p><h4 id="圆形图标" tabindex="-1">圆形图标 <a class="header-anchor" href="#圆形图标" aria-label="Permalink to &quot;圆形图标&quot;">​</a></h4><p>为了允许更快地渲染图标，这有主要的性能影响，你可以将 <a href="https://github.com/yairm210/Unciv/blob/master/android/Images.Icons/OtherIcons/Circle.png" target="_blank" rel="noreferrer">&quot;OtherIcons/circle.png&quot;</a> 复制到：</p><ul><li>&quot;ImprovementIcons/Circle.png&quot; 用于改良设施</li><li>&quot;ResourceIcons/Circle.png&quot; 用于资源</li><li>&quot;TechIcons/Circle.png&quot; 用于科技</li><li>&quot;ConstructionIcons/Circle.png&quot; 用于建筑和单位</li><li>&quot;StatIcons/Circle.png&quot; 用于统计</li></ul><h3 id="纹理打包器设置" tabindex="-1">纹理打包器设置 <a class="header-anchor" href="#纹理打包器设置" aria-label="Permalink to &quot;纹理打包器设置&quot;">​</a></h3><p>内置在 Unciv 中的纹理打包器将在每个 <code>Images</code> 目录中查找 <code>TexturePacker.settings</code> 文件（<em>不在</em> <code>jsons</code> 下）。 使用此文件，你可以调整打包器 - 例如控制像素插值过滤器。 它是一个 <a href="https://libgdx.com/wiki/tools/texture-packer#settings" target="_blank" rel="noreferrer">Gdx TexturePacker.Settings</a> 实例的 json。 如果你提供了设置文件，默认设置如上面链接的 Gdx 文档中所示，但如果没有这样的文件，某些字段有不同的默认值。 要获得这些更改的默认值，请使用以下内容作为自定义 <code>TexturePacker.settings</code> 文件的基础：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">	&quot;fast&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">	&quot;combineSubdirectories&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">	&quot;maxWidth&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2048</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">	&quot;maxHeight&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2048</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">	&quot;paddingX&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">	&quot;paddingY&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">	&quot;duplicatePadding&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">	&quot;filterMin&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;MipMapLinearLinear&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">	&quot;filterMag&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;MipMapLinearLinear&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>（如果你的图集名称以&quot;Icons&quot;结尾，请将&quot;filterMag&quot;更改为&quot;Linear&quot;。）</p><h3 id="纹理图集编码" tabindex="-1">纹理图集编码 <a class="header-anchor" href="#纹理图集编码" aria-label="Permalink to &quot;纹理图集编码&quot;">​</a></h3><p>由于某些情况，请确保将在图集中映射的名称和路径<strong>仅使用 ascii</strong>。抱歉，加载器的所有部分并不强制严格的 UTF-8 使用。 如果你不注意这一点，症状是：模组在中文 Windows 框上有效，但在西方框上无效，反之亦然，或者模组在中文 Windows 框上有效，但在中文 Linux 框上无效，反之亦然，或者模组在具有默认设置的中文 Windows 框上有效，但在打开&quot;使用 unicode UTF-8 进行全球语言支持&quot;的同一框上无效。 这在技术上不适用于使用多个图集时的图集名称本身（&quot;Images.xyz&quot;中的 xyz 部分），但为了保持一致性，我们仍然建议相同的规则。</p><h2 id="永久视听模组" tabindex="-1">永久视听模组 <a class="header-anchor" href="#永久视听模组" aria-label="Permalink to &quot;永久视听模组&quot;">​</a></h2><p>以下章节描述了在模组<em><strong>活动</strong></em>时将起作用的可能性。 它要么为当前游戏选择（在新游戏创建期间，对于保存的游戏之后不能更改），意味着将使用其所有规则和资源。 _或者_它在模组管理器中被标记为&#39;Permanent audiovisual mod&#39;（你必须在&#39;已安装&#39;列中选择它以获得复选框）。 在这种情况下，只有图形和音频将处于活动状态，规则更改将被忽略（如果它包含任何），除非第一种方式_也_被使用。 请注意，此功能在_所有_游戏中包括来自所选模组的图形或声音，甚至包括在安装模组之前开始的游戏。 重复：在模组同时带来更改的规则和视听的情况下，&#39;permanent&#39;功能将只在所有游戏中包括媒体，要使用规则，你仍然需要为新游戏选择模组。</p><p>请注意，模组作者可以（并且通常应该）使用 <a href="/Unciv/zh/Modders/Mod-file-structure/5-Miscellaneous-JSON-files.html#modoptionsjson">ModOptions</a> <a href="/Unciv/zh/Modders/uniques.html#modoptions-uniques">Uniques</a>控制复选框是否出现。</p><h2 id="覆盖内置图形" tabindex="-1">覆盖内置图形 <a class="header-anchor" href="#覆盖内置图形" aria-label="Permalink to &quot;覆盖内置图形&quot;">​</a></h2><p>如果模组提供与基础游戏中包含的图像同名同路径的图像（并且其图集是最新的），并且模组处于活动状态，则将使用模组的图形而不是内置图形。</p><p>例如，如果你在模组中包含名为&quot;Images/OtherIcons/Link.png&quot;的文件，你将覆盖 Civilopedia 中表示链接行的小链环图标。路径的第一部分与覆盖无关，它控制一组图集文件中的哪个将携带图像，但对于游戏中的选择，只有路径的其余部分是相关的。因此，要覆盖&quot;Images.Tech/TechIcons/Archery.png&quot;，你可以将图像放置为&quot;Images/TechIcons/Archery.png&quot;，它将起作用，因为&quot;TechIcons/Archery&quot;部分是关键。</p><p>请注意，就像添加项目一样，你的图形应该保持原始的大小和颜色选择，否则结果可能会令人惊讶，例如当游戏尝试对这样的图像进行着色时。</p><h2 id="提供其他图形" tabindex="-1">提供其他图形 <a class="header-anchor" href="#提供其他图形" aria-label="Permalink to &quot;提供其他图形&quot;">​</a></h2><p>你需要为新元素提供图形 - 就像新文明一样，新单位需要其图标。规则是：</p><ul><li>图像文件的路径和名称需要符合规则：<code>Image[.AtlasName]/Type-specific/Objectname.png</code>（Type-specific 表示科技的&quot;TechIcons&quot;，文明的&quot;NationIcons&quot;等。请参阅原版游戏文件夹。Objectname 是 json 中定义的确切名称，在翻译之前。）</li><li>所有路径部分都区分大小写。</li><li>单位像素精灵和 <a href="/Unciv/zh/Modders/Creating-a-custom-tileset.html">地形集</a>遵循特殊规则。</li><li>如果 <code>UnitIcons/&amp;lt;UnitName&amp;gt;.png</code> 不存在，我们将回退到 <code>UnitTypeIcons/&amp;lt;UnitType&amp;gt;.png</code> - 这允许为整个类型的单位设置单个图像，而无需摆弄每个单位</li><li>晋升可以命名为&quot;<code>[Unitname] ability</code>&quot;。在这种情况下，如果 <code>UnitIcons/Unitname.png</code> 存在，当 <code>UnitPromotionIcons/Unitname ability.png</code> 缺失时，它将回退到该单位图标。</li><li>晋升可以命名为&quot;Something I&quot;（或&quot; II&quot;或&quot; III&quot;）。后缀将被移除并绘制为小星星，只加载基本 <code>UnitPromotionIcons/Something.png</code>。</li><li>晋升的特殊规则可以组合，例如&quot;<code>[Warrior] ability III</code>&quot;将回退到 Warrior 单位图标并在其上绘制 3 个星。</li></ul><p>此外，还有一些图像类型，游戏具有显示能力但不自己提供图形，如下一段所述：</p><h3 id="添加自定义字体" tabindex="-1">添加自定义字体 <a class="header-anchor" href="#添加自定义字体" aria-label="Permalink to &quot;添加自定义字体&quot;">​</a></h3><p>你可以向游戏添加自定义 <code>.ttf</code> 字体：将 <code>.ttf</code> 文件放在模组的 <code>/fonts/</code> 目录内。你添加的字体将在 <code>Options-Advanced</code> 选项卡的字体列表顶部可见并可选择，格式为 <code>&amp;lt;fontname&amp;gt; (&amp;lt;modname&amp;gt;)</code>。</p><p>所有字体默认以 50 像素大小渲染，稍后根据游戏需要重新缩放。目前字体在缩小时不是 mipmapped 的。</p><h3 id="覆盖特殊字符" tabindex="-1">覆盖特殊字符 <a class="header-anchor" href="#覆盖特殊字符" aria-label="Permalink to &quot;覆盖特殊字符&quot;">​</a></h3><p>EmojiIcons 子文件夹中的纹理和一些其他纹理在特定代码点映射到字体中。游戏使用它们，可以在模组的任何文本中使用，并且可以被模组纹理覆盖。 此外，某些代码点通常由所选系统字体提供，但如果模组提供它们，则有 EmojiIcons 名称将覆盖字体字形（下表中的标记为&#39;optional&#39;）。 请注意，为这些代码点提供的纹理<em>确实</em>尊重纵横比，它们<em>不需要</em>像许多内置图标那样是正方形！</p><table tabindex="0"><thead><tr><th style="text-align:center;">符号</th><th style="text-align:center;">代码点</th><th style="text-align:left;">Unicode 名称</th><th style="text-align:left;">纹理路径</th><th style="text-align:center;">可选</th></tr></thead><tbody><tr><td style="text-align:center;">⛏</td><td style="text-align:center;">U+26CF</td><td style="text-align:left;">pick</td><td style="text-align:left;">EmojiIcons/Automate</td><td style="text-align:center;"></td></tr><tr><td style="text-align:center;">♪</td><td style="text-align:center;">U+266A</td><td style="text-align:left;">eighth note</td><td style="text-align:left;">EmojiIcons/Culture</td><td style="text-align:center;"></td></tr><tr><td style="text-align:center;">☠</td><td style="text-align:center;">U+2620</td><td style="text-align:left;">skull and crossbones</td><td style="text-align:left;">EmojiIcons/Death</td><td style="text-align:center;"></td></tr><tr><td style="text-align:center;">☮</td><td style="text-align:center;">U+262E</td><td style="text-align:left;">peace symbol</td><td style="text-align:left;">EmojiIcons/Faith</td><td style="text-align:center;"></td></tr><tr><td style="text-align:center;">⁂</td><td style="text-align:center;">U+2042</td><td style="text-align:left;">asterism</td><td style="text-align:left;">EmojiIcons/Food</td><td style="text-align:center;"></td></tr><tr><td style="text-align:center;">¤</td><td style="text-align:center;">U+00A4</td><td style="text-align:left;">currency sign</td><td style="text-align:left;">EmojiIcons/Gold</td><td style="text-align:center;"></td></tr><tr><td style="text-align:center;">♬</td><td style="text-align:center;">U+266C</td><td style="text-align:left;">sixteenth note</td><td style="text-align:left;">EmojiIcons/Great Artist</td><td style="text-align:center;"></td></tr><tr><td style="text-align:center;">⚒</td><td style="text-align:center;">U+2692</td><td style="text-align:left;">hammer</td><td style="text-align:left;">EmojiIcons/Great Engineer</td><td style="text-align:center;"></td></tr><tr><td style="text-align:center;">⛤</td><td style="text-align:center;">U+26E4</td><td style="text-align:left;">pentagram</td><td style="text-align:left;">EmojiIcons/Great General</td><td style="text-align:center;"></td></tr><tr><td style="text-align:center;">⚖</td><td style="text-align:center;">U+2696</td><td style="text-align:left;">scale</td><td style="text-align:left;">EmojiIcons/Great Merchant</td><td style="text-align:center;"></td></tr><tr><td style="text-align:center;">⚛</td><td style="text-align:center;">U+269B</td><td style="text-align:left;">atom</td><td style="text-align:left;">EmojiIcons/Great Scientist</td><td style="text-align:center;"></td></tr><tr><td style="text-align:center;">⌣</td><td style="text-align:center;">U+2323</td><td style="text-align:left;">smile</td><td style="text-align:left;">EmojiIcons/Happiness</td><td style="text-align:center;"></td></tr><tr><td style="text-align:center;">∞</td><td style="text-align:center;">U+221E</td><td style="text-align:left;">infinity</td><td style="text-align:left;">EmojiIcons/Infinity</td><td style="text-align:center;">*</td></tr><tr><td style="text-align:center;">⚙</td><td style="text-align:center;">U+2699</td><td style="text-align:left;">gear</td><td style="text-align:left;">EmojiIcons/Production</td><td style="text-align:center;"></td></tr><tr><td style="text-align:center;">⍾</td><td style="text-align:center;">U+237E</td><td style="text-align:left;">bell symbol</td><td style="text-align:left;">EmojiIcons/Science</td><td style="text-align:center;"></td></tr><tr><td style="text-align:center;">￪</td><td style="text-align:center;">U+FFEA</td><td style="text-align:left;">halfwidth upwards arrow</td><td style="text-align:left;">EmojiIcons/SortedAscending</td><td style="text-align:center;">*</td></tr><tr><td style="text-align:center;">◉</td><td style="text-align:center;">U+25C9</td><td style="text-align:left;">fisheye</td><td style="text-align:left;">EmojiIcons/SortedByStatus</td><td style="text-align:center;">*</td></tr><tr><td style="text-align:center;">⌚</td><td style="text-align:center;">U+231A</td><td style="text-align:left;">watch</td><td style="text-align:left;">EmojiIcons/SortedByTime</td><td style="text-align:center;">*</td></tr><tr><td style="text-align:center;">￬</td><td style="text-align:center;">U+FFEC</td><td style="text-align:left;">halfwidth upwards arrow</td><td style="text-align:left;">EmojiIcons/SortedDescending</td><td style="text-align:center;">*</td></tr><tr><td style="text-align:center;">✯</td><td style="text-align:center;">U+272F</td><td style="text-align:left;">pinwheel star</td><td style="text-align:left;">EmojiIcons/Star</td><td style="text-align:center;">*</td></tr><tr><td style="text-align:center;">⏳</td><td style="text-align:center;">U+23F3</td><td style="text-align:left;">hourglass</td><td style="text-align:left;">EmojiIcons/Turn</td><td style="text-align:center;"></td></tr><tr><td style="text-align:center;">ⅰ</td><td style="text-align:center;">U+2170</td><td style="text-align:left;">small roman numeral one</td><td style="text-align:left;">MayaCalendar/0</td><td style="text-align:center;"></td></tr><tr><td style="text-align:center;">ⅱ</td><td style="text-align:center;">U+2171</td><td style="text-align:left;">small roman numeral two</td><td style="text-align:left;">MayaCalendar/1</td><td style="text-align:center;"></td></tr><tr><td style="text-align:center;">ⅲ</td><td style="text-align:center;">U+2172</td><td style="text-align:left;">small roman numeral three</td><td style="text-align:left;">MayaCalendar/2</td><td style="text-align:center;"></td></tr><tr><td style="text-align:center;">ⅳ</td><td style="text-align:center;">U+2173</td><td style="text-align:left;">small roman numeral four</td><td style="text-align:left;">MayaCalendar/3</td><td style="text-align:center;"></td></tr><tr><td style="text-align:center;">ⅴ</td><td style="text-align:center;">U+2174</td><td style="text-align:left;">small roman numeral five</td><td style="text-align:left;">MayaCalendar/4</td><td style="text-align:center;"></td></tr><tr><td style="text-align:center;">ⅵ</td><td style="text-align:center;">U+2175</td><td style="text-align:left;">small roman numeral six</td><td style="text-align:left;">MayaCalendar/5</td><td style="text-align:center;"></td></tr><tr><td style="text-align:center;">ⅶ</td><td style="text-align:center;">U+2176</td><td style="text-align:left;">small roman numeral seven</td><td style="text-align:left;">MayaCalendar/6</td><td style="text-align:center;"></td></tr><tr><td style="text-align:center;">ⅷ</td><td style="text-align:center;">U+2177</td><td style="text-align:left;">small roman numeral eight</td><td style="text-align:left;">MayaCalendar/7</td><td style="text-align:center;"></td></tr><tr><td style="text-align:center;">ⅸ</td><td style="text-align:center;">U+2178</td><td style="text-align:left;">small roman numeral nine</td><td style="text-align:left;">MayaCalendar/8</td><td style="text-align:center;"></td></tr><tr><td style="text-align:center;">ⅹ</td><td style="text-align:center;">U+2179</td><td style="text-align:left;">small roman numeral ten</td><td style="text-align:left;">MayaCalendar/9</td><td style="text-align:center;"></td></tr><tr><td style="text-align:center;">ⅺ</td><td style="text-align:center;">U+217A</td><td style="text-align:left;">small roman numeral eleven</td><td style="text-align:left;">MayaCalendar/10</td><td style="text-align:center;"></td></tr><tr><td style="text-align:center;">ⅻ</td><td style="text-align:center;">U+217B</td><td style="text-align:left;">small roman numeral twelve</td><td style="text-align:left;">MayaCalendar/11</td><td style="text-align:center;"></td></tr><tr><td style="text-align:center;">ⅼ</td><td style="text-align:center;">U+217C</td><td style="text-align:left;">small roman numeral fifty</td><td style="text-align:left;">MayaCalendar/12</td><td style="text-align:center;"></td></tr><tr><td style="text-align:center;">ⅽ</td><td style="text-align:center;">U+217D</td><td style="text-align:left;">small roman numeral one hundred</td><td style="text-align:left;">MayaCalendar/13</td><td style="text-align:center;"></td></tr><tr><td style="text-align:center;">ⅾ</td><td style="text-align:center;">U+217E</td><td style="text-align:left;">small roman numeral five hundred</td><td style="text-align:left;">MayaCalendar/14</td><td style="text-align:center;"></td></tr><tr><td style="text-align:center;">ⅿ</td><td style="text-align:center;">U+217F</td><td style="text-align:left;">small roman numeral one thousand</td><td style="text-align:left;">MayaCalendar/15</td><td style="text-align:center;"></td></tr><tr><td style="text-align:center;">ↀ</td><td style="text-align:center;">U+2180</td><td style="text-align:left;">roman numeral one thousand cd</td><td style="text-align:left;">MayaCalendar/16</td><td style="text-align:center;"></td></tr><tr><td style="text-align:center;">ↁ</td><td style="text-align:center;">U+2181</td><td style="text-align:left;">roman numeral five thousand</td><td style="text-align:left;">MayaCalendar/17</td><td style="text-align:center;"></td></tr><tr><td style="text-align:center;">ↂ</td><td style="text-align:center;">U+2182</td><td style="text-align:left;">roman numeral ten thousand</td><td style="text-align:left;">MayaCalendar/18</td><td style="text-align:center;"></td></tr><tr><td style="text-align:center;">Ↄ</td><td style="text-align:center;">U+2183</td><td style="text-align:left;">roman numeral reversed one hundred</td><td style="text-align:left;">MayaCalendar/19</td><td style="text-align:center;"></td></tr><tr><td style="text-align:center;">ය</td><td style="text-align:center;">U+0DBA</td><td style="text-align:left;">sinhala letter yayanna</td><td style="text-align:left;">MayaCalendar/Baktun</td><td style="text-align:center;"></td></tr><tr><td style="text-align:center;">ඹ</td><td style="text-align:center;">U+0DB9</td><td style="text-align:left;">sinhala letter amba bayanna</td><td style="text-align:left;">MayaCalendar/Katun</td><td style="text-align:center;"></td></tr><tr><td style="text-align:center;">ම</td><td style="text-align:center;">U+0DB8</td><td style="text-align:left;">sinhala letter mayanna</td><td style="text-align:left;">MayaCalendar/Tun</td><td style="text-align:center;"></td></tr><tr><td style="text-align:center;">➡</td><td style="text-align:center;">U+27A1</td><td style="text-align:left;">black rightwards arrow</td><td style="text-align:left;">StatIcons/Movement</td><td style="text-align:center;"></td></tr><tr><td style="text-align:center;">…</td><td style="text-align:center;">U+2026</td><td style="text-align:left;">horizontal ellipsis</td><td style="text-align:left;">StatIcons/Range</td><td style="text-align:center;"></td></tr><tr><td style="text-align:center;">‡</td><td style="text-align:center;">U+2021</td><td style="text-align:left;">double dagger</td><td style="text-align:left;">StatIcons/RangedStrength</td><td style="text-align:center;"></td></tr><tr><td style="text-align:center;">†</td><td style="text-align:center;">U+2020</td><td style="text-align:left;">dagger</td><td style="text-align:left;">StatIcons/Strength</td><td style="text-align:center;"></td></tr></tbody></table><h3 id="添加奇观启动画面" tabindex="-1">添加奇观启动画面 <a class="header-anchor" href="#添加奇观启动画面" aria-label="Permalink to &quot;添加奇观启动画面&quot;">​</a></h3><p>你可以向模组添加奇观图像，当奇观完成时，它们将代替标准图标显示。图像需要是 .png 并且比例为 2:1，例如 200x100 像素。</p><p>将图像添加到 <code>/Images/WonderImages/</code>。它们需要根据 <code>Buildings.json</code> 中的名称字段命名，例如&quot;Temple of Artemis.png&quot;或&quot;Stonehenge.png&quot;</p><p>记住，为了与移动设备兼容，需要生成一个新的图集，包括这些。</p><h3 id="添加领袖肖像" tabindex="-1">添加领袖肖像 <a class="header-anchor" href="#添加领袖肖像" aria-label="Permalink to &quot;添加领袖肖像&quot;">​</a></h3><p>基础游戏没有领袖肖像，但能够在问候、Civilopedia、外交屏幕或文明选择器中显示它们。模组可以通过将图像添加到 <code>/Images/LeaderIcons/</code> 来提供这些。文件名必须与 Nations.json 中定义的文明领袖名称完全对应，否则它们将被忽略。</p><p>这些效果最好，如果它们是正方形，在 100x100 和 256x256 像素之间，并且在该区域内包含一些透明边框。</p><p>例如，<a href="https://github.com/yairm210/Unciv-leader-portrait-mod-example" target="_blank" rel="noreferrer">这里</a>是一个显示如何添加领袖肖像的模组，它可以补充基础游戏。</p><h3 id="添加肖像" tabindex="-1">添加肖像 <a class="header-anchor" href="#添加肖像" aria-label="Permalink to &quot;添加肖像&quot;">​</a></h3><p>基础游戏使用扁平图标，周围有彩色圆圈作为背景（例如，为了单位以适应文明的旗帜颜色），以表示 UI 中的实体，例如：单位、建筑、科技、资源、改良设施、宗教、晋升、Uniques、单位行动和文明。模组可以通过向 <code>/Images/&amp;lt;entityType&amp;gt;Portraits/</code>（例如 <code>/Images/BuildingPortraits/</code>、<code>/Images/ResourcePortraits/</code> 等）添加图像来提供&quot;肖像&quot; - 将保持未着色的静态图像 - 这些图像将在所有 UI 元素中使用（世界地图中的单位图标除外）。文件名必须与相应 JSON（例如 Units.json、Buildings.json、TileResources.json 等）中定义的单位/建筑/科技/资源等名称完全对应，或者与它们应该替换的文件同名，否则它们将被忽略。</p><p>如果模组提供&#39;/Images/&lt;entityType&gt;Portraits/Background.png&#39;图像，它们将被用作相应肖像的背景，而不是默认圆圈。肖像和背景效果最好，如果它们是完整的 RGB 正方形，在 100x100 和 256x256 像素之间，并且在该区域内包含一些透明边框。</p><p>例如，<a href="https://github.com/vegeta1k95/Civ-5-Icons" target="_blank" rel="noreferrer">这里</a>是一个显示如何添加自定义肖像的模组，它可以补充基础游戏。</p><p>可用的 <code>&amp;lt;entityType&amp;gt;Portraits/</code> 包括：</p><ul><li>UnitPortraits</li><li>BuildingPortraits</li><li>TechPortraits</li><li>ResourcePortraits</li><li>ImprovementPortraits</li><li>UnitPromotionPortraits</li><li>UniquePortraits</li><li>NationPortraits</li><li>ReligionPortraits</li><li>UnitActionPortraits</li></ul><h3 id="为单位类型添加图标" tabindex="-1">为单位类型添加图标 <a class="header-anchor" href="#为单位类型添加图标" aria-label="Permalink to &quot;为单位类型添加图标&quot;">​</a></h3><p>如 <a href="/Unciv/zh/Modders/Mod-file-structure/4-Unit-related-JSON-files.html#unittypesjson">UnitTypes.json</a> 中定义的单位类型在基础游戏中没有图标，但如果你提供名为&#39;Images/UnitTypeIcons/&lt;UnitType&gt;.png&#39;的图像，Civilopedia 可以装饰它们的条目。 （当你这样做时，你可以覆盖单位类型_类别标题_的默认图标 - 它是同一文件夹中的&#39;UnitTypes.png&#39;，或者用于移动域的图标 - &#39;DomainLand&#39;、&#39;DomainWater&#39;、&#39;DomainAir&#39;）</p><h3 id="为信仰添加图标" tabindex="-1">为信仰添加图标 <a class="header-anchor" href="#为信仰添加图标" aria-label="Permalink to &quot;为信仰添加图标&quot;">​</a></h3><p>单独的信仰 - 与 <a href="/Unciv/zh/Modders/Mod-file-structure/2-Civilization-related-JSON-files.html#beliefsjson">Beliefs.json</a> 中定义的信仰类型相反 - 在基础游戏中没有图标，但如果你提供名为&#39;Images/ReligionIcons/&lt;Belief&gt;.png&#39;的图像，Civilopedia 可以装饰它们的条目。 Civilopedia 回退到信仰类型的图标 - 正如你在基础游戏中看到的那样，但如果存在单独的图标，它们具有优先权。</p><h3 id="添加胜利插图" tabindex="-1">添加胜利插图 <a class="header-anchor" href="#添加胜利插图" aria-label="Permalink to &quot;添加胜利插图&quot;">​</a></h3><p>你可以为每个胜利启用图片，说明它们的进度。这可能是一艘正在建造的宇宙飞船，显示你添加的部分，或者是完成政策分支时的文化进步。它们将显示在胜利屏幕的新选项卡上。</p><p>为此，你需要创建多个图像。在以下内容中，<code>&amp;lt;&amp;gt;</code> 表示 <a href="/Unciv/zh/Modders/Mod-file-structure/5-Miscellaneous-JSON-files.html#victorytypesjson">VictoryTypes.json</a> 中出现的名称，未翻译，这些文件名（像 Unciv 中的任何其他文件名一样）区分大小写。所有文件都是可选的，除非如注明的 Background：</p><ul><li><code>VictoryIllustrations/&amp;lt;name&amp;gt;/Background.png</code> - 这决定整体尺寸，其他不得超出其大小，理想情况下应该具有相同的大小。强制性的，如果此文件缺失，则不会显示此胜利类型的插图。</li><li><code>VictoryIllustrations/&amp;lt;name&amp;gt;/Won.png</code> - 如果_你_（查看玩家）赢了这场胜利，则显示。</li><li><code>VictoryIllustrations/&amp;lt;name&amp;gt;/Lost.png</code> - 如果竞争对手赢了这场胜利，或者你已经完成了这场胜利，但之前赢得了另一场胜利，则显示。</li><li><code>VictoryIllustrations/&amp;lt;name&amp;gt;/&amp;lt;milestone&amp;gt;.png</code> - 对于 <code>milestones</code> 字段中每个没有 <code>[amount]</code> 的条目，一个图像，名称逐字采用但_不带_方括号，保留空格。</li><li><code>VictoryIllustrations/&amp;lt;name&amp;gt;/&amp;lt;milestone&amp;gt; &amp;lt;index&amp;gt;.png</code> - 对于 <code>milestones</code> 字段中带有 <code>[amount]</code> 的条目，每个步骤一个图像，从索引 1 开始。</li><li><code>VictoryIllustrations/&amp;lt;name&amp;gt;/&amp;lt;component&amp;gt;.png</code> - 对于 <code>requiredSpaceshipParts</code> 字段中每个唯一条目一个图像，即对于只能建造一次的部分。单位名称中的空格必须保留。</li><li><code>VictoryIllustrations/&amp;lt;name&amp;gt;/&amp;lt;component&amp;gt; &amp;lt;index&amp;gt;.png</code> - 对于必须建造多次的 <code>requiredSpaceshipParts</code> 字段中的部分，每个实例一个。单位名称中的空格必须保留，并且名称和索引之间必须有一个空格。索引从 1 开始。</li></ul><p>记住 - 这些是逻辑名称，因为它们在你的图集文件中编入索引，如果你让 Unciv 为你打包，<code>VictoryIllustrations</code> 文件夹应该放在 <code>&amp;lt;mod&amp;gt;/Images</code> 下 - 或者如果你想在这些图像占用单独的 <code>Victories.atlas</code>，则放在 <code>&amp;lt;mod&amp;gt;/Images.Victories</code> 下（即使留空也不要省略 <code>Images</code> 文件夹，纹理打包器需要它作为标记来执行其任务）。</p><p>这几乎就是全部 - 不需要 json，并且作为<a href="#永久视听模组">&#39;Permanent audiovisual mod&#39;</a>工作。Background 图像是触发器，如果存在，所有部分图像也必须存在，否则你的宇宙飞船在起飞前坠毁，带走了 Unciv。那是个玩笑，所有其他图像都是可选的，如果你遗漏了错误的图像，它可能看起来很无聊。</p><p>至于&quot;几乎&quot; - 所有图像都一个接一个地覆盖在 Background 图像上，所以它们必须都是相同的大小。除了 Won 和 Lost - 如果满足它们的情况，它们将_替换_整个其余部分，所以它们可以与背景不同的大小。部分图像以不保证的顺序覆盖在背景图像上，因此它们应该使用_透明度_来避免相互隐藏。</p><p>创建一组的一种方法是取一个最终图像，选择所有应该是中心部分本身而不是背景的部分（使用套索、魔棒或类似工具，根据需要使用抗锯齿和羽化），复制并粘贴为新图层。然后对背景图层上的选择应用去饱和和/或曲线，只留下完成胜利的外观暗示。现在拆解中心部分 - 进行适合一个部分名称的选择，复制并粘贴为新图层（就位），然后从原始中心部分图层中删除所选部分。冲洗并重复，然后单独导出每个图层为具有适当文件名的 png。 没有建议的大小，但请记住纹理最大为 2048x2048 像素，如果你希望图像正确打包，几个应该适合一个纹理。如果需要，它们将缩小到不超过屏幕大小的 80%，保留纵横比。</p><h2 id="声音" tabindex="-1">声音 <a class="header-anchor" href="#声音" aria-label="Permalink to &quot;声音&quot;">​</a></h2><p>标准值如下。声音本身可以在<a href="https://github.com/yairm210/Unciv/tree/master/android/assets/sounds" target="_blank" rel="noreferrer">这里</a>找到。</p><ul><li><em>arrow, artillery, bombard, bombing, cannon, chimes, choir, click, coin, construction, elephant, fortify, gdrAttack, horse, jetgun, machinegun, metalhit, missile, nonmetalhit, nuke, paper, policy, promote, setup, shipguns, shot, slider, swap, tankshot, throw, torpedo, upgrade, whoosh</em>。</li></ul><p>模组可以添加自己的声音，只要 attackSound 中的任何新值在模组的声音文件夹中都有相应的声音文件，使用 mp3、ogg 或 wav 之一格式（文件扩展名必须与使用的编解码器匹配）。记住，名称区分大小写。强烈建议小尺寸，Unciv 自己的声音使用 24kHz 联合立体声 8 位 VBR，大约 50-100kBps。</p><h2 id="覆盖内置声音" tabindex="-1">覆盖内置声音 <a class="header-anchor" href="#覆盖内置声音" aria-label="Permalink to &quot;覆盖内置声音&quot;">​</a></h2><p>这与图形的工作方式类似，除了不涉及图集。例如，你包含 sounds/Click.mp3，它将代替正常的点击声音播放。这些文件必须保持简短和小。未压缩时大于 1MB 的声音可能会在移动设备上中断或根本不播放。Unciv 尝试标准化为 24kHz 采样率、联合立体声、低比特率 VBR（-128kbps）mp3。只识别 mp3 和 ogg 格式（但现有的 mp3 可以用 ogg 文件覆盖）。</p><h2 id="提供其他音乐" tabindex="-1">提供其他音乐 <a class="header-anchor" href="#提供其他音乐" aria-label="Permalink to &quot;提供其他音乐&quot;">​</a></h2><p>模组 /music 文件夹中的声音文件（mp3 或 ogg）将在模组活动时被识别和使用。除了下一段描述的上下文特定音乐外，曲目将从所有可用曲目中随机播放（有一点偏见以避免曲目的接近重复）。没有覆盖 - 模组中的&quot;thatched-villagers.mp3&quot;将与基础游戏为你下载的文件一起播放，并且具有相同的可能性。比特率或长度没有硬性的技术限制，但大的带宽要求可能会导致口吃（&quot;下一回合&quot;的结束，就在世界地图更新之前，以及对于非常大的地图，最有可能导致这种情况）。</p><h3 id="上下文敏感的音乐-概述" tabindex="-1">上下文敏感的音乐：概述 <a class="header-anchor" href="#上下文敏感的音乐-概述" aria-label="Permalink to &quot;上下文敏感的音乐：概述&quot;">​</a></h3><p>音乐控制器通常会一个接一个地播放曲目，之间有一个暂停（可以在选项中更改）。当打开&quot;Leave game?&quot;确认对话框时，播放将淡出并暂停，并在关闭时可以恢复。</p><p>游戏代码中有各种&#39;触发器&#39;启动对新曲目的选择。新曲目将（如果需要）在开始播放之前快速淡出当前正在播放的曲目。曲目选择涉及触发器提供的上下文和随机因素，并尝试不重复任何曲目，直到至少其他八个曲目已播放。</p><p>模组可以提供自己的音乐文件夹，如果它们处于活动状态，其内容将与主音乐文件夹中的内容完全相同。模组应该通过仔细选择文件名来控制其曲目的使用。模组开发人员可以监视控制台输出，以获取记录触发器参数或加载错误的曲目选择消息。</p><p>一个曲目是特殊的：Thatched Villagers（另请参阅 credits.md）。如果音乐文件夹为空，游戏可以下载它，并且在使用音乐音量滑块时播放。如果某些问题发生，它也是回退曲目（但是，损坏的文件将关闭播放器，直到另一个触发器发生）。</p><h3 id="上下文敏感的音乐-触发器列表" tabindex="-1">上下文敏感的音乐：触发器列表 <a class="header-anchor" href="#上下文敏感的音乐-触发器列表" aria-label="Permalink to &quot;上下文敏感的音乐：触发器列表&quot;">​</a></h3><p>触发器通过可选地提供前缀和/或后缀来匹配文件名来指示上下文（称之为意图、情绪、无论什么，这无关紧要）。还有一些标志也会影响选择或行为 - 一个标志功能是使前缀或后缀成为强制性的，意味着如果没有可用的文件匹配，曲目选择器将什么都不做。否则，将通过排序然后选择第一个条目始终从可用列表中选择下一曲目。排序按优先级顺序进行：前缀匹配、后缀匹配、最近播放和一个随机数。因此，由于目前没有触发器具有空前缀，除非匹配请求前缀的文件少于八个，否则匹配没有任何前缀的文件将永远不会播放。</p><p>当前的触发器列表如下：</p><table tabindex="0"><thead><tr><th>描述</th><th style="text-align:left;">前缀</th><th style="text-align:center;">[^M]</th><th style="text-align:right;">后缀</th><th style="text-align:center;">[^X]</th><th style="text-align:center;">标志</th></tr></thead><tbody><tr><td>自动下一曲目[^0]</td><td style="text-align:left;"></td><td style="text-align:center;"></td><td style="text-align:right;">Ambient</td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr><tr><td>启动游戏[^1]</td><td style="text-align:left;"></td><td style="text-align:center;"></td><td style="text-align:right;">Menu</td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr><tr><td>每 10 回合</td><td style="text-align:left;">(玩家文明名称)</td><td style="text-align:center;">[^M]</td><td style="text-align:right;">Peace or War[^2]</td><td style="text-align:center;"></td><td style="text-align:center;">[^F]</td></tr><tr><td>新游戏：选择模组</td><td style="text-align:left;">(模组名称)</td><td style="text-align:center;">[^M]</td><td style="text-align:right;">Theme</td><td style="text-align:center;"></td><td style="text-align:center;">[^S]</td></tr><tr><td>新游戏：为玩家选择文明</td><td style="text-align:left;">(文明名称)</td><td style="text-align:center;">[^M]</td><td style="text-align:right;">Theme or Peace</td><td style="text-align:center;"></td><td style="text-align:center;">[^S]</td></tr><tr><td>外交：选择玩家</td><td style="text-align:left;">(文明名称)</td><td style="text-align:center;">[^M]</td><td style="text-align:right;">Peace or War[^3]</td><td style="text-align:center;"></td><td style="text-align:center;">[^S]</td></tr><tr><td>首次接触[^4]</td><td style="text-align:left;">(文明名称)</td><td style="text-align:center;">[^M]</td><td style="text-align:right;">Theme or Peace</td><td style="text-align:center;">[^X]</td><td style="text-align:center;"></td></tr><tr><td>宣战[^5]</td><td style="text-align:left;">(文明名称)</td><td style="text-align:center;">[^M]</td><td style="text-align:right;">War</td><td style="text-align:center;">[^X]</td><td style="text-align:center;"></td></tr><tr><td>文明被击败</td><td style="text-align:left;">(胜利/文明名称)</td><td style="text-align:center;"></td><td style="text-align:right;">Defeat</td><td style="text-align:center;">[^X]</td><td style="text-align:center;"></td></tr><tr><td>玩家获胜</td><td style="text-align:left;">(胜利/文明名称)</td><td style="text-align:center;"></td><td style="text-align:right;">Victory</td><td style="text-align:center;">[^X]</td><td style="text-align:center;"></td></tr><tr><td>黄金时代</td><td style="text-align:left;">(文明名称)</td><td style="text-align:center;">[^M]</td><td style="text-align:right;">Golden</td><td style="text-align:center;">[^X]</td><td style="text-align:center;"></td></tr><tr><td>奇观建成</td><td style="text-align:left;">(奇观名称)</td><td style="text-align:center;">[^M]</td><td style="text-align:right;">Wonder</td><td style="text-align:center;">[^X]</td><td style="text-align:center;"></td></tr><tr><td>科技研究完成</td><td style="text-align:left;">(科技名称)</td><td style="text-align:center;">[^M]</td><td style="text-align:right;">Researched</td><td style="text-align:center;">[^X]</td><td style="text-align:center;"></td></tr><tr><td>地图编辑器：选择文明起始位置</td><td style="text-align:left;">(文明名称)</td><td style="text-align:center;">[^M]</td><td style="text-align:right;">Theme</td><td style="text-align:center;"></td><td style="text-align:center;">[^S]</td></tr><tr><td>选项：音量滑块或默认曲目下载</td><td style="text-align:left;"></td><td style="text-align:center;"></td><td style="text-align:right;"></td><td style="text-align:center;"></td><td style="text-align:center;">[^D]</td></tr><tr><td>音乐控制（选项或从菜单）下一曲目</td><td style="text-align:left;"></td><td style="text-align:center;"></td><td style="text-align:right;">Ambient</td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr></tbody></table><p>图例：</p><ul><li><code>[^N]</code>: <strong>未实现</strong></li><li><code>[^M]</code>: 前缀必须匹配。如果未找到匹配的文件，触发器将什么都不做。</li><li><code>[^X]</code>: 后缀必须匹配。如果未找到匹配的文件，触发器将什么都不做。</li><li><code>[^S]</code>: 播放后停止。没有自动下一次选择。</li><li><code>[^F]</code>: 替换曲目的慢速淡出。</li><li><code>[^D]</code>: 始终播放默认文件。</li><li><code>[^0]</code>: 每当曲目完成并且配置的静默已经过去时，选择一个没有任何上下文的&#39;Ambient&#39;曲目。也由&#39;resume&#39;触发（例如，在 Android 上切换到另一个应用并返回）</li><li><code>[^1]</code>: 主菜单的首次打开（或初始语言选择器）。</li><li><code>[^2]</code>: 活跃玩家是否与任何人处于战争状态。</li><li><code>[^3]</code>: 根据你与所选玩家的关系。</li><li><code>[^4]</code>: 排除城邦。</li><li><code>[^5]</code>: 当另一个玩家向你宣战时的警报以及在外交屏幕中自己宣战。</li></ul><h2 id="提供领袖声音" tabindex="-1">提供领袖声音 <a class="header-anchor" href="#提供领袖声音" aria-label="Permalink to &quot;提供领袖声音&quot;">​</a></h2><p>以文明名称和相应文本消息的<a href="/Unciv/zh/Modders/Mod-file-structure/2-Civilization-related-JSON-files.html#nationsjson">字段名称</a>命名的声音文件，放置在模组的 <code>voices</code> 文件夹中，每当显示该消息时都会播放。文明名称和消息名称必须用点&#39;.&#39;连接，例如 <code>voices/Zulu.defeated.ogg</code>。</p><p>领袖声音音频剪辑将被流式传输，而不是缓存，所以它们可以很长 - 但是，如果需要播放另一个领袖声音或城市环境声音，它们将被切断而没有淡出 还要注意，城邦领袖的声音仅适用于城邦实际可以使用的那些消息：<code>attacked</code>、<code>defeated</code> 和 <code>introduction</code>。</p><h2 id="模组彩蛋" tabindex="-1">模组彩蛋 <a class="header-anchor" href="#模组彩蛋" aria-label="Permalink to &quot;模组彩蛋&quot;">​</a></h2><p>以下是 Unciv 将识别的特殊日期（或日期范围）列表：</p><table tabindex="0"><thead><tr><th>名称</th><th></th><th></th><th></th></tr></thead><tbody><tr><td>AprilFoolsDay</td><td>Friday13th</td><td>Qingming</td><td>UncivBirthday</td></tr><tr><td>DiaDeLosMuertos</td><td>LunarNewYear</td><td>Samhain</td><td>Xmas</td></tr><tr><td>Diwali</td><td>Passover</td><td>StarWarsDay</td><td>YuleGoat</td></tr><tr><td>Easter</td><td>PrideDay</td><td>TowelDay</td><td></td></tr></tbody></table><p>... 这些是什么时候或它们意味着什么 - 查找它，如果有疑问，在我们的来源中（😈）。</p><p>视听模组（用户<strong>必须</strong>然后将其标记为永久）可以定义名为<code>&quot;EasterEggs/name&amp;lt;index&amp;gt;&quot;</code>的纹理，其中名称必须与上表中的名称完全对应，索引从 1 开始计数。 示例：<code>&amp;lt;mod&amp;gt;/Images/EasterEggs/Diwali1.png</code> 等等。 然后，Unciv 将在相应日期的主菜单屏幕上显示它们为&quot;浮动艺术&quot;。它们将不时地从屏幕外出现，滑过窗口，并从另一侧消失，具有不同的角度和速度。</p><p>注意：</p><ul><li>你可以通过启动 jar 并在命令行中包含 <code>-DeasterEgg=name</code> 来测试这一点。</li><li>在重叠的假期的情况下，只选择一个 - 并且较长假期的&quot;影响&quot;通过减少与天数成反比的几率来平衡。例如，DiaDeLosMuertos 是两天，所以这两天每次 Unciv 启动都有 50% 的机会显示彩蛋。</li><li>Unciv 的&quot;基于地图的&quot;彩蛋独立工作！</li><li>没有文化偏见。如果你知道我们应该包含日期测试的一个不错的习俗，只需询问。</li></ul>`,93)])])}const p=e(d,[["render",i]]);export{h as __pageData,p as default};
